return function(a,b)local c=a:CreateTab("🎬 Графика",nil)local d=game:GetService("UserInputService")local e=game:GetService("Lighting")local f={}local g=false;local h={}local i=nil;local j=nil;local k=2;local l=Color3.new(1,1,1)local m=70;local n=false;local function o()if n then return end;n=true;if e.GlobalShadows~=false then e.GlobalShadows=false end;if e.ShadowSoftness~=0 then e.ShadowSoftness=0 end;if e.Brightness~=k then e.Brightness=k end;if e.Ambient~=l then e.Ambient=l end;local p=workspace.CurrentCamera;if p and p.FieldOfView~=m then p.FieldOfView=m end;n=false end;local function q()f.GlobalShadows=e.GlobalShadows;f.ShadowSoftness=e.ShadowSoftness;f.Brightness=e.Brightness;f.Ambient=e.Ambient;f.FOV=workspace.CurrentCamera and workspace.CurrentCamera.FieldOfView or 70;o()local r={"GlobalShadows","ShadowSoftness","Brightness","Ambient"}for s,t in ipairs(r)do local u=e:GetPropertyChangedSignal(t):Connect(o)table.insert(h,u)end;if workspace.CurrentCamera then i=workspace.CurrentCamera:GetPropertyChangedSignal("FieldOfView"):Connect(o)end end;local function v()for s,u in ipairs(h)do if u then u:Disconnect()end end;h={}if i then i:Disconnect()i=nil end;n=true;e.GlobalShadows=f.GlobalShadows;e.ShadowSoftness=f.ShadowSoftness;e.Brightness=f.Brightness;e.Ambient=f.Ambient;if workspace.CurrentCamera then workspace.CurrentCamera.FieldOfView=f.FOV end;n=false end;local function w()if g then v()end;for s,u in ipairs(h)do if u then u:Disconnect()end end;if i then i:Disconnect()end;h=nil;f=nil;i=nil;o=nil;q=nil;v=nil end;local x;x=c:CreateToggle({Name="Яркий свет и Без теней",CurrentValue=false,Flag="LightingToggle",Callback=function(y)g=y;if g then q()else v()end end})c:CreateKeybind({Name="Клавиша активации",CurrentKeybind="Y",HoldToInteract=false,Flag="LightingKeybind",Callback=function(z)if x then x:Set(not g)end end})return w end